('sc-037', 'scr-037', 'add', 'sk-fs-gr-h2heat', 'FS-GR-03', 'Hydrogen and process-heat interfaces', 'واجهات الهيدروجين والحرارة الصناعية', 'Added "Hydrogen and process-heat interfaces"', 'أُضيفت «واجهات الهيدروجين والحرارة الصناعية»', '{}'::jsonb, '{"name_en":"Hydrogen and process-heat interfaces","name_ar":"واجهات الهيدروجين والحرارة الصناعية","key_level":2,"lifecycle":"emerging","version":1,"obsolete_on":null,"replaced_by":null,"review_due":"2028-07-01","level_essence_en":"Explains how nuclear heat and power can feed hydrogen and industrial heat users, and the safety and grid questions each interface raises.","level_essence_ar":"يشرح كيف يمكن للحرارة والكهرباء النوويتين تزويد مستخدمي الهيدروجين والحرارة الصناعية، وأسئلة السلامة والشبكة التي تثيرها كل واجهة.","alt_labels_en":["Nuclear cogeneration","Clean hydrogen production"],"alt_labels_ar":["التوليد المشترك النووي","إنتاج الهيدروجين النظيف"]}'::jsonb, null, 1, array['sk-fs-gr-h2heat']::text[], null, '2026-08-25', true, array['catalogue','skills_outlook','skill_forecasts','skills_health','datasheet']::text[], array['training_manager','hr_director']::text[], 'instructor', '2026-08-25T11:00:00Z', null, '[{"label":"IEA World Energy Employment 2025 and IRENA/ILO Renewable Energy and Jobs 2025","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025"},{"label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"},{"label":"ENEC · ADNOC strategic collaboration (Nov 2024)","url":"https://www.enec.ae/en/news/latest-news/enec-and-adnoc-to-explore-the-use-of-advanced-nuclear-technologies-and-excess-heat-utilization-for-oil-and-gas-operations/"}]'::jsonb),
('sc-038', 'scr-038', 'add', 'sk-fs-gr-grid', 'FS-GR-04', 'Grid integration and flexible operation', 'التكامل مع الشبكة والتشغيل المرن', 'Added "Grid integration and flexible operation"', 'أُضيفت «التكامل مع الشبكة والتشغيل المرن»', '{}'::jsonb, '{"name_en":"Grid integration and flexible operation","name_ar":"التكامل مع الشبكة والتشغيل المرن","key_level":2,"lifecycle":"emerging","version":1,"obsolete_on":null,"replaced_by":null,"review_due":"2028-08-01","level_essence_en":"Understands how a nuclear fleet works alongside solar, storage and the grid operator, including load-following limits and grid-code duties.","level_essence_ar":"يفهم كيف يعمل أسطول نووي إلى جانب الطاقة الشمسية والتخزين ومشغّل الشبكة، بما في ذلك حدود متابعة الأحمال والتزامات كود الشبكة.","alt_labels_en":["Load following","Grid code compliance"],"alt_labels_ar":["متابعة الأحمال","الامتثال لكود الشبكة"]}'::jsonb, null, 1, array['sk-fs-gr-grid']::text[], null, '2026-08-25', true, array['catalogue','skills_outlook','skill_forecasts','skills_health','datasheet']::text[], array['training_manager','hr_director']::text[], 'instructor', '2026-08-25T11:00:00Z', null, '[{"label":"IEA World Energy Employment 2025 and IRENA/ILO Renewable Energy and Jobs 2025","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025"},{"label":"WNN · UAE''s first reactor starts supplying power","url":"https://www.world-nuclear-news.org/articles/uaes-first-reactor-starts-supplying-power"}]'::jsonb),
